template.css:
html, body {
  margin: 0;
  padding: 0;
  font-family: Arial, Helvetica, sans-serif;
  color: #000;
}
.label {
  box-sizing: border-box;
  width: 63mm;
  height: 38mm;
  padding: 2.2mm 2.4mm 1.8mm;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.name {
  font-size: 12px;
  font-weight: 700;
  line-height: 1.15;
  max-height: 2.3em;
  overflow: hidden;
}
.price {
  font-size: 18px;
  font-weight: 800;
  margin-top: 1mm;
  line-height: 1;
  letter-spacing: -0.02em;
}
.currency {
  font-size: 10px;
  font-weight: 700;
  margin-left: 0.8mm;
}
.codes {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 2.5mm;
  margin-top: auto;
}
.barcode-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.4mm;
  min-width: 0;
  flex: 1 1 auto;
}
img.barcode {
  height: 13mm;
  width: 100%;
  max-width: 100%;
  object-fit: contain;
  object-position: center bottom;
}
.code {
  font-size: 8.5px;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-align: center;
  white-space: nowrap;
}
img.qr {
  height: 12mm;
  width: 12mm;
  flex: 0 0 auto;
}
